-- BIBLIOTECA XTENSOR · Modo abierto solicitado por el usuario.
-- 1. Ejecute este archivo COMPLETO en SQL Editor de Supabase.
-- 2. Publique index.html en Vercel como sitio estático, sin build.
-- 3. En el HTML ingrese Project URL y Publishable key / anon key.
-- No requiere usuarios. Lectura y guardado públicos. No use claves secretas.
-- Reejecutable: no reemplaza datos ni historial existentes.
begin;
create table if not exists public.biblioteca_estado (
 id integer primary key check(id=1), version bigint not null default 1,
 contenido jsonb not null check(jsonb_typeof(contenido)='object'),
 actualizado timestamptz not null default now()
);
create table if not exists public.biblioteca_historial (
 version bigint primary key,contenido jsonb not null,motivo text not null,
 creado timestamptz not null default now()
);
alter table public.biblioteca_estado enable row level security;
alter table public.biblioteca_historial enable row level security;
drop policy if exists biblioteca_abierta_lectura on public.biblioteca_estado;
create policy biblioteca_abierta_lectura on public.biblioteca_estado for select to anon,authenticated using(true);
drop policy if exists biblioteca_abierta_historial on public.biblioteca_historial;
create policy biblioteca_abierta_historial on public.biblioteca_historial for select to anon,authenticated using(true);
revoke all on public.biblioteca_estado,public.biblioteca_historial from anon,authenticated;
grant select on public.biblioteca_estado,public.biblioteca_historial to anon,authenticated;
create or replace function public.biblioteca_guardar(p_version bigint,p_contenido jsonb,p_motivo text)
returns bigint language plpgsql security definer set search_path='' as $$
declare v bigint;
begin
 if jsonb_typeof(p_contenido) is distinct from 'object'
 or jsonb_typeof(p_contenido->'data'->'maquinas') is distinct from 'array'
 or jsonb_typeof(p_contenido->'data'->'piezas') is distinct from 'array'
 or jsonb_typeof(p_contenido->'data'->'relaciones') is distinct from 'array'
 or jsonb_typeof(p_contenido->'data'->'incidencias') is distinct from 'array'
 or jsonb_typeof(p_contenido->'data'->'fuentes') is distinct from 'array'
 then raise exception 'Estructura de biblioteca inválida'; end if;
 if octet_length(p_contenido::text)>40000000 then raise exception 'Biblioteca mayor de 40 MB'; end if;
 if exists(select 1 from jsonb_array_elements(p_contenido->'data'->'relaciones') r where
   not exists(select 1 from jsonb_array_elements(p_contenido->'data'->'piezas') p where p->>'id'=r->>'pieza')
   or not exists(select 1 from jsonb_array_elements(p_contenido->'data'->'maquinas') m where m->>'id'=r->>'maquina'))
 then raise exception 'Relaciones con piezas o máquinas inexistentes'; end if;
 select version into v from public.biblioteca_estado where id=1 for update;
 if v is distinct from p_version then raise exception 'CONFLICTO_VERSION: otra persona guardó cambios. Exporte su borrador, recargue la biblioteca y vuelva a aplicar los cambios.'; end if;
 insert into public.biblioteca_historial(version,contenido,motivo) select version,contenido,left(coalesce(p_motivo,'Actualización'),500) from public.biblioteca_estado where id=1;
 update public.biblioteca_estado set contenido=p_contenido,version=v+1,actualizado=now() where id=1;
 return v+1;
end $$;
revoke all on function public.biblioteca_guardar(bigint,jsonb,text) from public;
grant execute on function public.biblioteca_guardar(bigint,jsonb,text) to anon,authenticated;
create or replace view public.biblioteca_piezas with(security_invoker=true) as select p->>'id' as id,p->>'codigo' as codigo,p->>'nombre' as nombre,p->>'tipo' as tipo,p as ficha from public.biblioteca_estado e cross join lateral jsonb_array_elements(e.contenido->'data'->'piezas') p where e.id=1;
create or replace view public.biblioteca_maquinas with(security_invoker=true) as select m->>'id' as codigo,m->>'nombre' as nombre,m->>'categoria' as categoria,m as ficha from public.biblioteca_estado e cross join lateral jsonb_array_elements(e.contenido->'data'->'maquinas') m where e.id=1;
create or replace view public.biblioteca_relaciones with(security_invoker=true) as select r->>'maquina' as maquina,r->>'pieza' as pieza,r->>'etapa' as etapa,r->>'origen' as origen,(r->>'cantidad')::numeric as cantidad,r->>'fuente' as fuente from public.biblioteca_estado e cross join lateral jsonb_array_elements(e.contenido->'data'->'relaciones') r where e.id=1;
grant select on public.biblioteca_piezas,public.biblioteca_maquinas,public.biblioteca_relaciones to anon,authenticated;
